def orfs(s, label):
    n=len(s)
    for f in range(3):
        i=f
        while i+3<=n:
            if s[i:i+3]=='ATG':
                j=i
                while j+3<=n and s[j:j+3]!='TAA' and s[j:j+3]!='TAG' and s[j:j+3]!='TGA':
                    j+=3
                if j+3<=n:
                    L=(j-i)//3
                    if L>=60:
                        print(f"{label} frame+{f+1} start={i+1} end={j+3} len_nt={j+3-i} aa={L} "
                              f"start_codon={s[i:i+3]} stop={s[j:j+3]}")
                        print("   ", "".join(code.get(s[k:k+3],'?') for k in range(i,j,3))[:120])
                i=j+3
            else:
                i+=3

